	private void assertParity(String shape, String query, String bindingName, Value value) {
		try (RepositoryConnection connection = repository.getConnection()) {
			MapBindingSet input = new MapBindingSet(1);
			input.addBinding(bindingName, value);
			List<BindingSet> nativeRows = evaluate(connection, query, input);
			List<BindingSet> serializedRows = evaluate(connection, SPARQLQueries.withInitialBindings(query, input),
					null);

			assertFalse(nativeRows.isEmpty(), shape + " must exercise a non-empty native result");
			assertEquals(bag(nativeRows), bag(serializedRows),
					shape + " must match the result bag from Query.setBinding");
		}
	}

	private void assertUnsupportedTransport(String shape, String query, String bindingName, Value value,
			Map<Map<String, Value>, Integer> expectedNativeBag, String scopeReason) {
		try (RepositoryConnection connection = repository.getConnection()) {
			MapBindingSet input = new MapBindingSet(1);
			input.addBinding(bindingName, value);
			List<BindingSet> nativeRows = evaluate(connection, query, input);
			assertEquals(expectedNativeBag, bag(nativeRows),
					shape + " native result bag is part of the transport contract");

			UnsupportedOperationException unsupported = assertThrows(UnsupportedOperationException.class,
					() -> SPARQLQueries.withInitialBindings(query, input),
					shape + " must be rejected when VALUES cannot preserve initial-binding semantics");
			assertTrue(unsupported.getMessage().contains(scopeReason),
					shape + " rejection must identify the unsupported scope: " + unsupported.getMessage());
		}
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection, String query, BindingSet bindings) {
		return evaluate(connection, query, bindings, null);
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection, String query, BindingSet bindings,
			Dataset dataset) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		tupleQuery.setDataset(dataset);
		if (bindings != null) {
			bindings.forEach(binding -> tupleQuery.setBinding(binding.getName(), binding.getValue()));
		}
		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = tupleQuery.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static Map<Map<String, Value>, Integer> bag(List<BindingSet> rows) {
		Map<Map<String, Value>, Integer> result = new HashMap<>();
		for (BindingSet row : rows) {
			Map<String, Value> values = new TreeMap<>();
			row.forEach(binding -> values.put(binding.getName(), binding.getValue()));
			result.merge(values, 1, Integer::sum);
		}
		return result;
	}

	private static Map<Map<String, Value>, Integer> bag(BindingSet... rows) {
		return bag(List.of(rows));
	}

	private static BindingSet binding(String name, Value value) {
		MapBindingSet row = new MapBindingSet(1);
		row.addBinding(name, value);
		return row;
	}
